using Xunit;

public class U21_LoggingTests
{
    [Fact]
    public void EventLog_NonEmpty()
    {
        // Arrange
        var logger = new Logger();

        // Act
        logger.LogEvent("Test event");

        // Assert
        Assert.True(logger.EventLog.Count > 0);
    }

    [Fact]
    public void EventLog_IncludesVentilationSettings()
    {
        // Arrange
        var logger = new Logger();
        var ventilationSettings = new VentilationSettings();

        // Act
        logger.LogEvent("Ventilation settings changed", ventilationSettings);

        // Assert
        Assert.Contains(logger.EventLog, e => e.Message.Contains("Ventilation settings changed"));
    }

    [Fact]
    public void EventLog_IncludesDateTime()
    {
        // Arrange
        var logger = new Logger();

        // Act
        logger.LogEvent("Test event");

        // Assert
        Assert.True(logger.EventLog.First().Timestamp != default(DateTime));
    }

    [Fact]
    public void EventLog_IncludesClockChange()
    {
        // Arrange
        var logger = new Logger();
        var originalDateTime = DateTime.Now;
        var newDateTime = originalDateTime.AddHours(1);

        // Act
        logger.LogClockChange(originalDateTime, newDateTime);

        // Assert
        Assert.Contains(logger.EventLog, e => e.Message.Contains("Current Date/Time") && e.Message.Contains("New Date/Time"));
    }
}
